#include "rxt_private.h"
#include "rf.h"
#include "dbg.h"

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

#define string "\r\n" "rxt "

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

void rxt_set_ready (Rxt_Rdy_Bit bit)
{
	if(rxt.enable)
	{
		rxt.ready.byte |= (1u << bit) ;
		rxt_ready_update () ;
	
		#if DBG_RXT == 1
		  dbg_tx_text (string) ;
		  dbg_tx_text ("ready: ") ;
		  dbg_tx_h8 (rxt.ready.byte) ;
		#endif
	}
}

//--------------------------------------------------------------------------//

void rxt_clr_ready (Rxt_Rdy_Bit bit)
{
	if(rxt.enable)
	{
		rxt.ready.byte &= ~(1u << bit) ;
	
		#if DBG_RXT == 1
		  dbg_tx_text (string) ;
		  dbg_tx_text ("ready: ") ;
		  dbg_tx_h8 (rxt.ready.byte) ;
		#endif
	}
}

//--------------------------------------------------------------------------//
void rxt_ready_update (void)
{
	if(rxt.ready.byte == 0xFF)
	{
		rf_icon_clr  (ICON_NOT_READY , FALSE) ;
	}
	else
	{
		rf_icon_set  (ICON_NOT_READY , FALSE) ; 
	}
}

